import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { demoConfig } from "@/lib/demos";
import { env } from "@/lib/env";

const querySchema = z.object({
  lang: z.string(),
});

export async function GET(request: NextRequest) {
  const parsed = querySchema.safeParse({ lang: request.nextUrl.searchParams.get("lang") });
  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid language" }, { status: 400 });
  }

  const language = demoConfig.languages.find((lang) => lang.id === parsed.data.lang);
  if (!language) {
    return NextResponse.json({ error: "Language not found" }, { status: 404 });
  }

  try {
    const host = new URL(env.NEXT_PRIVATE_DEMO_HOST);
    host.port = String(language.port);
    const response = await fetch(host.toString(), { cache: "no-store" });
    const text = await response.text();

    const output = safeFormat(text);
    return NextResponse.json({ output });
  } catch (error) {
    return NextResponse.json({ output: language.snippet, notice: "Using snippet fallback" }, { status: 200 });
  }
}

function safeFormat(input: string) {
  try {
    const json = JSON.parse(input);
    return JSON.stringify(json, null, 2);
  } catch {
    return input.trim();
  }
}
